INSERT OR REPLACE INTO "projects" ("sort", "id", "slug", "name", "client", "year", "categories", "description", "image", "images") VALUES (26, '6fc51623-8604-4815-a29c-c940ba20c850', 'power-search', 'Power Search', 'Facebook', '2019', '["product-design","ideating-wireframing","design-system"]', 'Continued efforts to apply and test a new internal design system while improving a company-wide utility, Power Search.', '{"src":"/images/projects/power-search/cover-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]}', '[{"key":"09f40a797f44","image":{"src":"/images/projects/power-search/00-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Blank, pre-focus search state."},{"key":"33e81a0d990d","image":{"src":"/images/projects/power-search/01-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Preferred search and results layout."},{"key":"e2a1dc1e0441","image":{"src":"/images/projects/power-search/02-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Alternative layout proposal."},{"key":"2f5c9a3ba837","image":{"src":"/images/projects/power-search/03-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Typeahead results and suggestions loading behaviors."},{"key":"9fe6b656022e","image":{"src":"/images/projects/power-search/04-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Initial focusing of the search field input."},{"key":"fce31e84b8d4","image":{"src":"/images/projects/power-search/05-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Displaying typeahead content upon first keystroke input."},{"key":"dbfcb10a251b","image":{"src":"/images/projects/power-search/06-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Loaded typeahead results, matching, and beginning focus/tab-based navigation."},{"key":"b1f4cdc2619f","image":{"src":"/images/projects/power-search/07-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"\"Tokenizing\" multi-faceted search input with field types, operators, and value(s)."},{"key":"6e5004caee91","image":{"src":"/images/projects/power-search/08-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Multi-faceted input appending an additional value."},{"key":"b66addf91a4a","image":{"src":"/images/projects/power-search/09-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Stopped typing search input to arrow down and focus and select typeahead result."},{"key":"c179fd653292","image":{"src":"/images/projects/power-search/10-1920.webp","width":2560,"height":1600,"widths":[320,960,1920]},"alt":"Final \"tokenization\" of multi-faceted search input, ready for full search, typeahead selection, \"re-opeing\"/editing of previously closed parameters, or adding more inputs."}]');
