INSERT OR REPLACE INTO "references" ("sort", "id", "name", "title", "company", "linkedin_url", "initials", "quote") VALUES (0, 'reference-01', 'James Yu', 'Senior Software Engineer', 'Meta', 'https://www.linkedin.com/in/smarts2013/', 'JY', 'Leo volunteered to design for the Sticker Admin Tool for the Story Creation Team, which is one of our most important tools, to be used to deploy/manage sticker assets in sticker tray for public users. Historically, it has been a huge pain point as the old tool is lacking a lot of functionalities and very inefficient to use. Leo dedicated himself to this project with full passion and went full speed. After several iterations, the design was perfected and received very positive feedback from people across the whole Story Creation Team, which also made it to the ''Story of the Week.''');
INSERT OR REPLACE INTO "references" ("sort", "id", "name", "title", "company", "linkedin_url", "initials", "quote") VALUES (1, 'reference-02', 'Alexander Lambert', 'Design Director', 'BitGo', 'https://www.linkedin.com/in/abldotdesign/', 'AL', 'Leo is a deep thinker who lives in between design and code. While at BitGo, Leo took ownership of the design system by streamlining components, testing new UI elements within the product, and bridging those components with our UI repository. He''s excited to live in these two worlds by supporting both the design and front-end engineering teams. Previously, he led some of BitGo''s newest market growing spaces, including BitGo Prime and Go products, helping connect our users with partner services. Leo has a level head and pragmatic style required to design, build, launch, and maintain complex systems.');
INSERT OR REPLACE INTO "references" ("sort", "id", "name", "title", "company", "linkedin_url", "initials", "quote") VALUES (2, 'reference-03', 'Justin Harsch', 'Design Director', 'Inktel', 'https://www.linkedin.com/in/justinharsch', 'JH', 'Rarely do you meet a creative with such a lethal combination of technical skills and fundamental design ability. Leo can handle any project from classic graphic design to robust web projects using the latest technology with ease. It was a pleasure to work with someone who was never out of their element.');
INSERT OR REPLACE INTO "references" ("sort", "id", "name", "title", "company", "linkedin_url", "initials", "quote") VALUES (3, 'reference-04', 'Melissa Bazillion', 'Marketing Strategist', 'Emerson College', 'https://www.linkedin.com/in/melissabazillion', 'MB', 'I can''t stress the relief I felt every time Leo and I worked together. He is one of the most reliable partners and brings an incredible amount of creativity and expertise to every project.');
INSERT OR REPLACE INTO "references" ("sort", "id", "name", "title", "company", "linkedin_url", "initials", "quote") VALUES (4, 'reference-05', 'Bryce Trueman', 'Product Manager', 'BitGo', 'https://www.linkedin.com/in/brycetrueman/', 'BT', 'Leo is killing it on the design front! Thank you so much for your hard work and always pushing for what''s best for the customer! It''s been super fun working together and I''m beyond excited to get [our project] out to the world!');
